## Secure Access: Authentication & Authorization

Authentication verifies user identity, while authorization determines what actions they can perform. We'll implement a JWT-based authentication middleware in Moleculer to protect our service actions. This middleware decodes the JWT and attaches user information to the `context.meta` object. [JSON Web Tokens (JWT)](https://jwt.io/)

```typescript
// middlewares/auth.middleware.ts
import { ServiceBroker, Context, Middleware } from "moleculer";
import jwt from "jsonwebtoken";

const SECRET = process.env.JWT_SECRET || "super-secret-jwt-key";

export const AuthMiddleware = (broker: ServiceBroker): Middleware => {
  return {
    localAction(handler, action) {
      return async function(ctx: Context) {
        // Check if action requires authentication
        if (action.auth) {
          const authHeader = ctx.meta.headers?.authorization;
          if (!authHeader || !authHeader.startsWith("Bearer ")) {
            throw new Error("Authentication required.");
          }
          const token = authHeader.split(" ")[1];
          try {
            const decoded = jwt.verify(token, SECRET) as { id: string; roles: string[]; };
            ctx.meta.user = decoded; // Attach user info to context meta
          } catch (err) {
            throw new Error("Invalid or expired token.");
          }
        }
        return handler(ctx);
      };
    },
  };
};

