        <div class="product-list">
            <% products.forEach(product => { %>
                <div class="product-card">
                    <h2><%= product.name %></h2>
                    <p><%= product.description %></p>
                    <p class="price">$<%= product.price.toFixed(2) %></p>
                </div>
            <% }); %>
        </div>
    <% } else { %>
        <p>No products found.</p>
    <% } %>
</body>
</html>
```

