  });

  await fastify.register(fastifyWebsocket);

  fastify.get('/', async (request, reply) => {
    return { hello: 'world' };
  });

  return fastify;
};

// src/server.ts
import { buildApp } from './app';

const start = async () => {
  const fastify = await buildApp();
  try {
    await fastify.listen({ port: parseInt(process.env.PORT || '3000') });
  } catch (err) {
    fastify.log.error(err);
